(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.45)*8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [240+Math.sin(t*1.1)*60*Math.cos(t*0.2), 120+Math.cos(t*1.1)*60*Math.cos(t*0.2), 0.15, 3.0],
    [240+Math.sin(t*0.7+3)*80, 120+Math.cos(t*0.7+3)*80, 0.13, 2.8],
    [80+Math.sin(t*0.45)*50, 200+Math.cos(t*0.65)*40, 0.11, 2.1],
    [400+Math.cos(t*0.55)*60, 40+Math.sin(t*0.75)*50, 0.09, 2.4]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.cos(d*f*0.5 - t*sp*0.4 + 3.0);
  }
  const act = aS/src.length, inh = iS/src.length, hib = hS/src.length;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.07-t*1.5)*Math.sin(sy*0.06+t*1.3)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.08-ang*2+t*0.8))*0.3;
  const spiral2 = Math.sin(dist*0.12+ang*5-t*2.5)*0.15;
  const reaction1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const reaction2 = Math.tanh((hib*0.5 + act*0.3 - inh*0.4 + spiral2)*1.8);
  const combined = Math.tanh((reaction1*0.6 + reaction2*0.4 + spiral2*0.2)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.08-t*0.7)*Math.cos(sy*0.09+t*0.5)*0.3)*1.5)*0.3;
  const grain = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const vignette = 1.0 - Math.pow(dist/320, 2.5)*0.3;
  const blend = (combined*0.65 + cell*0.2 + grain) * vignette;
  const v = blend*0.5+0.5;
  const pal = [[5,12,45],[10,40,85],[15,75,120],[20,130,130],[45,165,120],[130,185,80],[210,195,55],[225,145,55],[200,90,60],[160,50,70],[100,30,65],[50,15,55],[15,10,48],[5,12,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8 + Math.sin(combined*Math.PI)*0.2;
  const edge = Math.abs(combined) > 0.7 ? 1.12 : Math.abs(combined) > 0.4 ? 1.05 : 1.0;
  const breathe = 0.95 + Math.sin(t*0.4)*0.05;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*breathe)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*breathe)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*breathe)|0
  ];
}
